<?php $files=["database/seeders/careers_data2.json","database/seeders/careers_data3.json","database/seeders/careers_data4.json","database/seeders/careers_data5.json","database/seeders/careers_data6.json","database/seeders/careers_data7.json","database/seeders/careers_data8.json","database/seeders/careers_data9.json","database/seeders/careers_data10.json"]; $all=[]; foreach($files as $f){ $raw=file_get_contents($f); $raw=preg_replace("/^\xEF\xBB\xBF/","",$raw); $raw=preg_replace("/^\xFF\xFE/","",$raw); $raw=mb_convert_encoding($raw,"UTF-8","UTF-16LE,UTF-8,ASCII"); $d=json_decode($raw,true); if($d) $all=array_merge($all,$d); else echo "FAIL($f): ".json_last_error_msg()."\n"; } file_put_contents("database/seeders/careers_data.json",json_encode($all,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)); echo count($all)." careers merged\n";
